using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    [ColumnName("Label")]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public class PredictionResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> ConfidenceScores { get; set; } = new();
}

public class TrainingResponse
{
    public string Status { get; set; } = string.Empty;
    public EvaluationMetrics Metrics { get; set; } = new();
}

public class EvaluationMetrics
{
    public double MacroAccuracy { get; set; }
    public double MicroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public double LogLossReduction { get; set; }
    public List<CategoryMetric> PerCategoryMetrics { get; set; } = new();
}

public class CategoryMetric
{
    public string Category { get; set; } = string.Empty;
    public double Precision { get; set; }
    public double Recall { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly string _dataPath;
    private readonly string _modelPath;
    private PredictionEngine<TicketData, TicketPrediction>? _predictionEngine;
    private string[] _categoryNames = [];
    private readonly object _lock = new();

    public bool IsModelTrained => _predictionEngine is not null;

    public TicketClassifierService(IWebHostEnvironment env)
    {
        _mlContext = new MLContext(seed: 0);
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
    }

    public TrainingResponse TrainAndEvaluate()
    {
        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Build the featurization + training pipeline
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label")
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        // Cross-validate on the full dataset to get evaluation metrics
        var cvResults = _mlContext.MulticlassClassification
            .CrossValidate(dataView, pipeline, numberOfFolds: 3);

        // Train the final model on all data
        var model = pipeline.Fit(dataView);

        // Save and load prediction engine
        _mlContext.Model.Save(model, dataView.Schema, _modelPath);
        LoadPredictionEngine(model, dataView);

        // Aggregate cross-validation metrics
        var avgMetrics = new EvaluationMetrics
        {
            MacroAccuracy = cvResults.Average(r => r.Metrics.MacroAccuracy),
            MicroAccuracy = cvResults.Average(r => r.Metrics.MicroAccuracy),
            LogLoss = cvResults.Average(r => r.Metrics.LogLoss),
            LogLossReduction = cvResults.Average(r => r.Metrics.LogLossReduction),
            PerCategoryMetrics = BuildPerCategoryMetrics(cvResults)
        };

        return new TrainingResponse
        {
            Status = "Model trained successfully",
            Metrics = avgMetrics
        };
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        if (_predictionEngine is null)
            throw new InvalidOperationException(
                "Model has not been trained. POST to /api/tickets/train first.");

        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        TicketPrediction prediction;
        lock (_lock)
        {
            prediction = _predictionEngine.Predict(ticketData);
        }

        var confidenceScores = new Dictionary<string, float>();
        for (var i = 0; i < _categoryNames.Length && i < prediction.Score.Length; i++)
        {
            confidenceScores[_categoryNames[i]] = prediction.Score[i];
        }

        return new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            ConfidenceScores = confidenceScores
        };
    }

    private void LoadPredictionEngine(ITransformer model, IDataView dataView)
    {
        lock (_lock)
        {
            _predictionEngine = _mlContext.Model
                .CreatePredictionEngine<TicketData, TicketPrediction>(model);
        }

        // Extract the label column key-value mapping to get category names
        var labelColumn = dataView.Schema["Label"];
        if (labelColumn.Type is Microsoft.ML.Data.KeyDataViewType)
        {
            var transformedData = model.Transform(dataView);
            var slotNames = new Microsoft.ML.Data.VBuffer<ReadOnlyMemory<char>>();
            transformedData.Schema["Score"].GetSlotNames(ref slotNames);
            _categoryNames = slotNames.DenseValues()
                .Select(v => v.ToString()).ToArray();
        }
    }

    private List<CategoryMetric> BuildPerCategoryMetrics(
        IReadOnlyList<Microsoft.ML.TrainCatalogBase
            .CrossValidationResult<Microsoft.ML.Data
            .MulticlassClassificationMetrics>> cvResults)
    {
        var metrics = new List<CategoryMetric>();
        var first = cvResults.FirstOrDefault()?.Metrics.PerClassLogLoss;
        if (first is null) return metrics;

        for (var i = 0; i < first.Count && i < _categoryNames.Length; i++)
        {
            var idx = i;
            metrics.Add(new CategoryMetric
            {
                Category = _categoryNames[idx],
                Precision = cvResults.Average(
                    r => idx < r.Metrics.ConfusionMatrix.PerClassPrecision.Count
                        ? r.Metrics.ConfusionMatrix.PerClassPrecision[idx] : 0),
                Recall = cvResults.Average(
                    r => idx < r.Metrics.ConfusionMatrix.PerClassRecall.Count
                        ? r.Metrics.ConfusionMatrix.PerClassRecall[idx] : 0)
            });
        }

        return metrics;
    }
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketsController : ControllerBase
{
    private readonly TicketClassifierService _classifier;

    public TicketsController(TicketClassifierService classifier)
    {
        _classifier = classifier;
    }

    /// <summary>
    /// Trains the model using the CSV data and returns evaluation metrics.
    /// </summary>
    [HttpPost("train")]
    public ActionResult<TrainingResponse> Train()
    {
        var result = _classifier.TrainAndEvaluate();
        return Ok(result);
    }

    /// <summary>
    /// Predicts the category for a support ticket.
    /// </summary>
    [HttpPost("predict")]
    public ActionResult<PredictionResponse> Predict([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) &&
            string.IsNullOrWhiteSpace(request.Description))
        {
            return BadRequest("Subject or Description is required.");
        }

        if (request.Priority < 1 || request.Priority > 3)
        {
            return BadRequest("Priority must be between 1 and 3.");
        }

        if (!_classifier.IsModelTrained)
        {
            return BadRequest("Model has not been trained. POST to /api/tickets/train first.");
        }

        var prediction = _classifier.Predict(request);
        return Ok(prediction);
    }
}

